/// Molar masses of the equations, kg/mol.
fn molar_mass(fluid: PureFluid) -> f64 {
    match fluid {
        PureFluid::Nitrogen => 0.028_013_48,
        PureFluid::Argon => 0.039_948,
        PureFluid::Helium => 0.004_002_602,
        PureFluid::CarbonDioxide => 0.044_009_8,
    }
}

/// `CoolProp`'s density reducing value divided into ours: `CoolProp` evaluates
/// nitrogen with `ρ_c` = 11 183.901 464 6 mol/m³ instead of the published
/// 11 183.9, so the same reduced density δ is a slightly different ρ. Comparing
/// at equal δ keeps the check exact; p and densities scale back by this factor.
fn reducing_ratio(fluid: PureFluid) -> f64 {
    match fluid {
        PureFluid::Nitrogen => 11_183.9 / 11_183.901_464_580_624,
        _ => 1.0,
    }
}

type Tables = (
    PureFluid,
    &'static [[f64; 8]],
    &'static [[f64; 4]],
    &'static [[f64; 3]],
);

fn tables() -> [Tables; 4] {
    [
        (
            PureFluid::Nitrogen,
            NITROGEN_STATES,
            NITROGEN_SATURATION,
            NITROGEN_PT,
        ),
        (PureFluid::Argon, ARGON_STATES, ARGON_SATURATION, ARGON_PT),
        (
            PureFluid::Helium,
            HELIUM_STATES,
            HELIUM_SATURATION,
            HELIUM_PT,
        ),
        (
            PureFluid::CarbonDioxide,
            CARBONDIOXIDE_STATES,
            CARBONDIOXIDE_SATURATION,
            CARBONDIOXIDE_PT,
        ),
    ]
}

fn close(name: &str, got: f64, want: f64, scale: f64, tolerance: f64) -> anyhow::Result<()> {
    let error = (got - want).abs() / scale.abs().max(want.abs());
    anyhow::ensure!(error < tolerance, "{name}: {got} vs {want} ({error:e})");
    Ok(())
}

#[test]
#[expect(
    clippy::many_single_char_names,
    reason = "thermodynamic symbols p, T, u, v, h, s, x"
)]
fn test_reference_fluids_match_coolprop_single_phase() -> anyhow::Result<()> {
    for (fluid, states, _, _) in tables() {
        let (m, k) = (molar_mass(fluid), reducing_ratio(fluid));
        let anchor = fluid.homogeneous(
            ThermodynamicTemperature::new::<kelvin>(300.0),
            MassDensity::new::<kilogram_per_cubic_meter>(m * k),
        )?;
        for &[t, rho, p, cv, cp, w, dh, ds] in states {
            let x = fluid.homogeneous(
                ThermodynamicTemperature::new::<kelvin>(t),
                MassDensity::new::<kilogram_per_cubic_meter>(rho * m * k),
            )?;
            let at = format!("{fluid:?} at {t} K, {rho} mol/m³");
            close(
                &format!("p {at}"),
                x.pressure.get::<pascal>() / k,
                p,
                1.0,
                1e-9,
            )?;
            let per_mole = |q: f64| q * m;
            close(
                &format!("cv {at}"),
                per_mole(x.cv.get::<joule_per_kilogram_kelvin>()),
                cv,
                1.0,
                1e-9,
            )?;
            close(
                &format!("cp {at}"),
                per_mole(x.cp.get::<joule_per_kilogram_kelvin>()),
                cp,
                1.0,
                1e-9,
            )?;
            close(
                &format!("w {at}"),
                x.speed_of_sound.get::<meter_per_second>(),
                w,
                1.0,
                1e-9,
            )?;
            let h = per_mole(
                x.enthalpy.get::<joule_per_kilogram>()
                    - anchor.enthalpy.get::<joule_per_kilogram>(),
            );
            let s = per_mole(
                x.entropy.get::<joule_per_kilogram_kelvin>()
                    - anchor.entropy.get::<joule_per_kilogram_kelvin>(),
            );
            // Differences from the anchor: absolute floors of 1 mJ/mol and 1e-6
            // J/(mol·K).
            close(&format!("Δh {at}"), h, dh, 1e3, 1e-9)?;
            close(&format!("Δs {at}"), s, ds, 10.0, 1e-9)?;
        }
    }
    Ok(())
}

#[test]
fn test_reference_fluids_match_coolprop_saturation() -> anyhow::Result<()> {
    for (fluid, _, saturation, _) in tables() {
        let (m, k) = (molar_mass(fluid), reducing_ratio(fluid));
        for &[t, p, rho_l, rho_v] in saturation {
            let sat = fluid.saturation(ThermodynamicTemperature::new::<kelvin>(t))?;
            let at = format!("{fluid:?} at {t} K");
            close(
                &format!("p_sat {at}"),
                sat.pressure.get::<pascal>() / k,
                p,
                1.0,
                1e-8,
            )?;
            close(
                &format!("ρ' {at}"),
                sat.liquid_density.get::<kilogram_per_cubic_meter>() / (m * k),
                rho_l,
                1.0,
                1e-8,
            )?;
            close(
                &format!("ρ'' {at}"),
                sat.vapour_density.get::<kilogram_per_cubic_meter>() / (m * k),
                rho_v,
                1.0,
                1e-8,
            )?;
        }
    }
    Ok(())
}

#[test]
fn test_reference_fluids_match_coolprop_density_at_pressure_and_temperature() -> anyhow::Result<()>
{
    for (fluid, _, _, states) in tables() {
        let (m, k) = (molar_mass(fluid), reducing_ratio(fluid));
        for &[t, p, rho] in states {
            let x = fluid.properties(
                Pressure::new::<pascal>(p * k),
                ThermodynamicTemperature::new::<kelvin>(t),
            )?;
            let got = x.density.get::<kilogram_per_cubic_meter>() / (m * k);
            close(
                &format!("ρ {fluid:?} at {t} K, {p} Pa"),
                got,
                rho,
                1.0,
                1e-9,
            )?;
        }
    }
    Ok(())
}
